&lt;li style=&quot;font-size: 12pt;&quot;&gt;&lt;span style=&quot;font-size: 12pt;&quot;&gt;&lt;span data-contrast=&quot;none&quot;&gt;&lt;span data-ccp-charstyle=&quot;normaltextrun&quot;&gt;Experience with hardware offloading on RDMA-capable NICs and how that integrates with&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-charstyle=&quot;normaltextrun&quot;&gt;virtual networking on&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-charstyle=&quot;normaltextrun&quot;&gt;Open V-switch&lt;/span&gt;&lt;span data-ccp-charstyle=&quot;normaltextrun&quot;&gt;, KVM/QEMU.&lt;/span&gt;&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:false,&amp;quot;134233118&amp;quot;:false,&amp;quot;201341983&amp;quot;:0,&amp;quot;335557856&amp;quot;:16777215,&amp;quot;335559685&amp;quot;:425,&amp;quot;335559738&amp;quot;:0,&amp;quot;335559739&amp;quot;:0,&amp;quot;335559740&amp;quot;:276,&amp;quot;335559991&amp;quot;:425,&amp;quot;469777462&amp;quot;:[720,426],&amp;quot;469777927&amp;quot;:[0,0],&amp;quot;469777928&amp;quot;:[0,8]}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-size: 12pt;&quot;&gt;&lt;span style=&quot;font-size: 12pt;&quot;&gt;&lt;span data-contrast=&quot;none&quot;&gt;&lt;span data-ccp-charstyle=&quot;normaltextrun&quot;&gt;Experience with&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-charstyle=&quot;normaltextrun&quot;&gt;managing production&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-charstyle=&quot;normaltextrun&quot;&gt;Kubernetes&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-charstyle=&quot;normaltextrun&quot;&gt;clusters and workloads&lt;/span&gt;&lt;span data-ccp-charstyle=&quot;normaltextrun&quot;&gt;&amp;nbsp;with an automation tool such as&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-charstyle=&quot;normaltextrun&quot;&gt;ArgoCD&lt;/span&gt;&lt;span data-ccp-charstyle=&quot;normaltextrun&quot;&gt;.&lt;/span&gt;&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:false,&amp;quot;134233118&amp;quot;:false,&amp;quot;201341983&amp;quot;:0,&amp;quot;335557856&amp;quot;:16777215,&amp;quot;335559685&amp;quot;:425,&amp;quot;335559738&amp;quot;:0,&amp;quot;335559739&amp;quot;:0,&amp;quot;335559740&amp;quot;:276,&amp;quot;335559991&amp;quot;:425,&amp;quot;469777462&amp;quot;:[720,426],&amp;quot;469777927&amp;quot;:[0,0],&amp;quot;469777928&amp;quot;:[0,8]}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/li&gt;
